import {
  type CommandPaletteLabels,
  type CommandPalette as Palette,
  type PaletteCommand,
  type PaletteResult,
  createCommandPalette,
} from "@cssints/headless";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { frame } from "cssints/frame" with { type: "cssints" };
import { surface } from "cssints/surface" with { type: "cssints" };
import {
  createContext,
  createEffect,
  createUniqueId,
  For,
  merge,
  omit,
  onSettled,
  Show,
  untrack,
  useContext,
} from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface CommandPaletteProps {
  /** The commands, declared once: the primitive filters them and the skin renders its results. */
  readonly commands: ReadonlyArray<PaletteCommand>;
  /** Every visible string; `title` names the dialog and the listbox, `placeholder` the field. */
  readonly labels?: Partial<CommandPaletteLabels>;
  /** The open state changed. The primitive owns it; this is the notification, not a control. */
  readonly onOpenChange?: (open: boolean) => void;
  /**
   * The chord the palette binds on the page (`"mod+k"`), or `false` to bind none. A host that wants it
   * scoped to its own element binds `createHotkeys` itself and calls `openPalette` from `onReady`.
   */
  readonly hotkey?: string | false;
  /** The element the layer is portalled into (default `document.body`). */
  readonly mount?: Element;
  /** The primitive, once: a host that binds its own chord opens the palette through it. */
  readonly onReady?: (palette: Palette) => void;
  readonly children?: JSX.Element;
}

export interface CommandPaletteContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface CommandPaletteTriggerProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface CommandPaletteInputProps extends Renderable<PartProps, void> {
  readonly class?: string;
  /** The field's name; without one the dialog's title names it. */
  readonly label?: string;
}

export interface CommandPaletteListProps extends Renderable<PartProps, void> {
  readonly class?: string;
}

/** What a row's `render` sees: whether the primitive names it as the active option. */
export interface CommandPaletteItemState {
  readonly highlighted: () => boolean;
}

export interface CommandPaletteItemProps extends Renderable<PartProps, CommandPaletteItemState> {
  /** The command's id: the primitive owns the option's id, its role and its announcement. */
  readonly id: string;
  readonly class?: string;
  /** The row's content; the command's label by default. */
  readonly children?: JSX.Element;
}

export interface CommandPaletteEmptyProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

const CommandPaletteContext = createContext<{
  readonly palette: Palette;
  readonly titleId: string;
  readonly mount: () => Element | undefined;
}>();

// The layer holds the page still and takes the wash; the panel floats above both, is a surface and a frame like a card, and
// sits high on the page rather than in its middle, which is what a palette is for: the reader is looking at the results, not
// at a box they centred on purpose.
const layerClass = css.cn(
  css.position("fixed"),
  css.inset("0"),
  // `z-index` takes an `<integer>`, which a `number` token is not: the custom property is the knob
  css.zIndex("var(--z-dialog)"),
  css.display("grid"),
  css.justifyItems("center"),
  css.alignItems("start"),
  css.padding(t.space._4),
  css.paddingBlockStart("12vh"),
  css.overflow("auto"),
);

const backdropClass = css.cn(css.position("absolute"), css.inset("0"), css.bg(t.color.scrim));

const panelClass = css.cn(
  frame().radius(t.radius.xl).padding(0).border("1px"),
  surface().color(t.color.overlayBackground),
  css.borderColor(t.color.overlayBorder),
  css.color(t.color.text),
  css.boxShadow(t.shadow.popover),
  css.position("relative"),
  css.display("flex"),
  css.flexDirection("column"),
  css.width("min(32rem, 100%)"),
  css.maxHeight("calc(100dvh - 12vh - 2 * 16px)"),
  // the field stays at the top and the results scroll under it
  css.overflow("hidden"),
  css.outline("none"),
);

const inputClass = css.cn(
  css.boxSizing("border-box"),
  css.width("100%"),
  css.padding(t.space._3, t.space._4),
  css.border("none"),
  css.borderBlockEnd("1px solid", t.color.border),
  css.bg("transparent"),
  css.color(t.color.fieldText),
  css.fontSize(t.font.sizeLg),
  // the field is the only control in the panel: it takes the focus on open and the caret is the indicator
  css.outline("none"),
);

const listClass = css.cn(
  css.display("flex"),
  css.flexDirection("column"),
  css.gap("2px"),
  css.padding(t.space._1),
  // the panel's max height bounds the list, and this is what lets it shrink to that bound and scroll
  css.minHeight("0"),
  css.overflowY("auto"),
);

const groupClass = css.cn(css.display("flex"), css.flexDirection("column"), css.gap("2px"));

const groupLabelClass = css.cn(
  css.padding(t.space._1, t.space._2),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("600"),
  css.color(t.color.muted),
);

// The APG combobox highlight: focus stays in the field and the primitive marks the active option with `aria-selected`, so
// the row paints the announcement and the kit keeps no copy of the active index. A pointer hover is the same attribute.
const itemClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.padding(t.space._1, t.space._2),
  css.borderRadius(t.radius.sm),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.attr("aria-selected", "true")(css.bg(t.color.buttonBackground)),
);

const emptyClass = css.cn(
  css.padding(t.space._3, t.space._2),
  css.fontSize(t.font.size),
  css.color(t.color.muted),
  css.textAlign("center"),
);

// Nothing to show, still nothing to see: the dialog's name and the live region are read, not looked at.
const silentClass = css.cn(
  css.position("absolute"),
  css.width("1px"),
  css.height("1px"),
  css.overflow("hidden"),
  css.clipPath("inset(50%)"),
  css.whiteSpace("nowrap"),
);

/**
 * APG command palette, styled: `CommandPaletteTrigger` opens it, `CommandPaletteContent` is the modal layer, and
 * `CommandPaletteInput`, `CommandPaletteList`, `CommandPaletteItem` and `CommandPaletteEmpty` are the query and the results.
 * `createCommandPalette` owns the dialog, the query, the filter (`results()` is what the skin renders, in the host's order),
 * the active option (`aria-activedescendant`), the arrows, Home and End, Enter, Escape, the focus into the field and back,
 * and the hotkey. The skin adds the scrim, the surface, the field, the grouped rows and the highlight.
 *
 * A palette is a dialog with a search field, not a combobox: the primitive announces the field as a `searchbox` because
 * choosing a row runs a command, it does not complete the field.
 */
export const CommandPalette = (props: CommandPaletteProps): JSX.Element => {
  const palette = createCommandPalette({
    commands: props.commands,
    get hotkey() {
      return typeof props.hotkey === "string" ? props.hotkey : undefined;
    },
    labels: props.labels,
    get onOpenChange() {
      return props.onOpenChange;
    },
  });
  // the page's chord, as the primitive's `attach` means it: `false` is the host saying it binds its own
  onSettled(() => (props.hotkey === false ? undefined : palette.attach()));
  // structural, read once: it is the primitive for a host that opens the palette itself
  untrack(() => props.onReady)?.(palette);

  return (
    <CommandPaletteContext
      value={{ palette, titleId: palette.titleProps.id, mount: () => props.mount }}
    >
      {props.children}
      {/* always mounted: a live region has to exist before its text changes */}
      <div {...palette.statusProps} data-part="command-palette-status" class={silentClass}>
        {palette.status()}
      </div>
    </CommandPaletteContext>
  );
};

/**
 * The layer, the wash and the panel. Nothing is in the DOM while the palette is closed; the field takes the focus when it
 * opens and the primitive returns it to whatever had it when it closes, and the page does not scroll under the scrim.
 *
 * The layer is portalled into `document.body` (or `mount`) so an ancestor's `transform`, `filter`, `contain` or `overflow`
 * can neither clip it nor become the containing block of its `position: fixed`.
 */
export const CommandPaletteContent = (props: CommandPaletteContentProps): JSX.Element => {
  const { palette, mount } = useContext(CommandPaletteContext);
  let scroll: string | undefined;
  createEffect(
    () => palette.open(),
    (open) => {
      if (open) {
        scroll = document.body.style.overflow;
        document.body.style.overflow = "hidden";
      } else if (scroll !== undefined) {
        document.body.style.overflow = scroll;
        scroll = undefined;
      }
    },
  );
  return (
    <Show when={palette.open()}>
      <Portal mount={mount()}>
        <div data-part="command-palette-layer" class={layerClass}>
          <div
            {...palette.backdropProps}
            data-part="command-palette-backdrop"
            class={backdropClass}
          />
          {renderPart(
            props,
            merge(omit(props, "render", "class", "children"), palette.dialogProps, () => ({
              "data-part": "command-palette",
              get class() {
                return css.cn(panelClass, props.class);
              },
            })),
            undefined,
            (part) => (
              <div {...part}>
                {/* the name the dialog and the listbox are labelled by: one id, rendered once */}
                <h2 {...palette.titleProps} data-part="command-palette-title" class={silentClass}>
                  {palette.labels.title}
                </h2>
                {props.children ?? (
                  <>
                    <CommandPaletteInput />
                    <CommandPaletteList />
                    <CommandPaletteEmpty />
                  </>
                )}
              </div>
            ),
          )}
        </div>
      </Portal>
    </Show>
  );
};

/** The button that opens the palette: `Button` unless `render` says otherwise. It is the element with `aria-haspopup`. */
export const CommandPaletteTrigger = (props: CommandPaletteTriggerProps): JSX.Element => {
  const { palette } = useContext(CommandPaletteContext);
  const rest = omit(props, "render", "class", "children");
  // `merge` reads these through, so a plain spread would freeze `aria-expanded`
  const merged = merge(rest, () => ({
    "aria-haspopup": "dialog" as const,
    get "aria-expanded"() {
      return palette.open() ? "true" : "false";
    },
    get "aria-controls"() {
      return palette.dialogProps.id;
    },
    onClick: () => palette.openPalette(),
    get class() {
      return css.cn(props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/**
 * The query field. The primitive owns its value, its `role="searchbox"`, its `aria-controls`, the active option's id and
 * the key handler; the skin names it by the dialog's title and gives it the panel's look.
 */
export const CommandPaletteInput = (props: CommandPaletteInputProps): JSX.Element => {
  const { palette, titleId } = useContext(CommandPaletteContext);
  const input = palette.inputProps;
  const merged = merge(omit(props, "render", "class", "label"), () => ({
    id: input.id,
    type: input.type,
    role: input.role,
    placeholder: input.placeholder,
    autoComplete: input.autoComplete,
    spellcheck: input.spellcheck,
    "aria-label": props.label,
    get "aria-labelledby"() {
      return props.label === undefined ? titleId : undefined;
    },
    get "aria-controls"() {
      return input["aria-controls"];
    },
    get "aria-activedescendant"() {
      return input["aria-activedescendant"];
    },
    get value() {
      return input.value;
    },
    onInput: input.onInput,
    onKeyDown: input.onKeyDown,
    "data-part": "command-palette-input",
    get class() {
      return css.cn(inputClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => <input {...part} />);
};

/**
 * The results: the primitive's `results()` in the host's order, one `role="group"` per `group` with its heading, and a row
 * per command. The skin filters nothing: what is not in `results()` is not rendered, so the empty state is the only thing
 * left when the query matches nothing.
 */
export const CommandPaletteList = (props: CommandPaletteListProps): JSX.Element => {
  const { palette } = useContext(CommandPaletteContext);
  // Group names and ids are strings, so `For` keeps a row (and its DOM) across a query that still matches it.
  const groups = (): ReadonlyArray<string | undefined> => {
    const names: Array<string | undefined> = [];
    for (const result of palette.results()) {
      if (!names.includes(result.group)) {
        names.push(result.group);
      }
    }
    return names;
  };
  const rows = (group: string | undefined): ReadonlyArray<string> =>
    palette
      .results()
      .filter((result) => result.group === group)
      .map((result) => result.id);

  const merged = merge(palette.listProps, () => ({
    "data-part": "command-palette-list",
    get class() {
      return css.cn(listClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>
      <For each={groups()}>
        {(group) => {
          const labelId = createUniqueId();
          return (
            <div
              role="group"
              data-part="command-palette-group"
              aria-labelledby={group === undefined ? undefined : labelId}
              class={groupClass}
            >
              <div
                id={group === undefined ? undefined : labelId}
                hidden={group === undefined}
                data-part="command-palette-group-label"
                class={groupLabelClass}
              >
                {group}
              </div>
              <For each={rows(group)}>{(id) => <CommandPaletteItem id={id} />}</For>
            </div>
          );
        }}
      </For>
    </div>
  ));
};

/**
 * One result: `role="option"`, its id, `tabindex="-1"` and `aria-selected` from the primitive, the command's label unless
 * `children` says. A press keeps the focus in the field (the primitive cancels the mouse-down) and runs the command.
 */
export const CommandPaletteItem = (props: CommandPaletteItemProps): JSX.Element => {
  const { palette } = useContext(CommandPaletteContext);
  const result = (): PaletteResult | undefined =>
    palette.results().find((candidate) => candidate.id === props.id);
  const merged = merge(
    () => palette.optionProps(props.id),
    () => ({
      "data-part": "command-palette-item",
      get class() {
        return css.cn(itemClass, props.class);
      },
    }),
  );
  const state: CommandPaletteItemState = {
    highlighted: () => palette.optionProps(props.id)["aria-selected"] === "true",
  };
  return renderPart(props, merged, state, (part) => (
    <div {...part}>{props.children ?? result()?.label}</div>
  ));
};

/** The empty state: the primitive hides it while a result exists. */
export const CommandPaletteEmpty = (props: CommandPaletteEmptyProps): JSX.Element => {
  const { palette } = useContext(CommandPaletteContext);
  const merged = merge(palette.emptyProps, () => ({
    "data-part": "command-palette-empty",
    get class() {
      return css.cn(emptyClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>{props.children ?? palette.labels.empty}</div>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import type { CommandPalette as Palette, PaletteCommand } from "@cssints/headless";
import { render } from "@solidjs/web";
import {
  CommandPalette,
  CommandPaletteContent,
  CommandPaletteTrigger,
} from "./command-palette.tsx";

/** What a mount hands the driver: the host ancestor, the palette itself, and the commands that ran. */
export interface MountedPalette {
  /** The element the palette was rendered into, which may be a transformed, clipped ancestor. */
  readonly root: HTMLElement;
  /** The commands that ran, by id, in order. */
  readonly chosen: ReadonlyArray<string>;
  readonly palette: () => Palette | undefined;
  readonly dispose: () => void;
}

export interface PaletteFixtureConfig {
  /** A `transform` and an `overflow: hidden` around the palette: the case the portal exists for. */
  readonly hostile?: boolean;
  /** The chord the palette binds on the page; `false` binds none. */
  readonly hotkey?: string | false;
  /** The host's own modal root, when it has one. */
  readonly mount?: Element;
}

const makeCommands = (chosen: string[]): ReadonlyArray<PaletteCommand> => [
  {
    id: "deploy",
    label: "Deploy",
    group: "Ship",
    keywords: ["release", "production"],
    run: () => {
      chosen.push("deploy");
    },
  },
  {
    id: "rollback",
    label: "Roll back",
    group: "Ship",
    run: () => {
      chosen.push("rollback");
    },
  },
  {
    id: "theme",
    label: "Toggle theme",
    group: "View",
    keywords: ["dark", "light"],
    run: () => {
      chosen.push("theme");
    },
  },
  {
    id: "settings",
    label: "Open settings",
    group: "View",
    keywords: ["preferences"],
    run: () => {
      chosen.push("settings");
    },
  },
];

/**
 * Mounts the styled palette the way a page does: a trigger button inside an optional transformed, clipped ancestor, and the
 * layer the part portals away. The host owns no open state — the primitive does, as the skin exposes it — so this records
 * the commands that ran and hands the primitive over for the assertions that need `results()` or `optionProps()`.
 *
 * @param {PaletteFixtureConfig} config the ancestor and the chord
 * @returns {MountedPalette} the mounted element and the driver's view of it
 */
export const mountPalette = (config: PaletteFixtureConfig = {}): MountedPalette => {
  const root = document.createElement("div");
  document.body.append(root);
  const chosen: string[] = [];
  let palette: Palette | undefined;
  const dispose = render(
    () => (
      <div
        data-part="palette-host"
        style={
          config.hostile === true
            ? { transform: "translateZ(0)", overflow: "hidden", height: "80px" }
            : undefined
        }
      >
        <CommandPalette
          commands={makeCommands(chosen)}
          hotkey={config.hotkey ?? false}
          mount={config.mount}
          onReady={(created) => {
            palette = created;
          }}
        >
          <CommandPaletteTrigger>Open the palette</CommandPaletteTrigger>
          <CommandPaletteContent />
        </CommandPalette>
      </div>
    ),
    root,
  );
  return {
    root,
    chosen,
    palette: () => palette,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

// A palette has no spec (it is a composition, not a pattern), so this drives the kit's own DOM rather than a scenario:
// read a part, press a key, type in the field, run a row. The kit's part names are the only contract it shares with the
// component.
import type { CommandPalette as Palette } from "@cssints/headless";
import { flush } from "solid-js";
import { userEvent } from "vite-plus/test/browser";
import type { MountedPalette } from "./command-palette.fixture.tsx";

const byPart = <T extends HTMLElement = HTMLElement>(name: string): T => {
  const element = document.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`the palette has no ${name}`);
  }
  return element;
};

/** The primitive the fixture handed back, or a failure: the mount did not render. */
export const paletteOf = (mounted: MountedPalette): Palette => {
  const palette = mounted.palette();
  if (palette === undefined) {
    throw new Error("the palette did not render");
  }
  return palette;
};

/** The layer, while the palette is open; `null` when it is closed and out of the DOM. */
export const layerOf = (): HTMLElement | null =>
  document.querySelector<HTMLElement>('[data-part="command-palette-layer"]');

export const panelOf = (): HTMLElement => byPart("command-palette");

export const inputOf = (): HTMLInputElement => byPart<HTMLInputElement>("command-palette-input");

export const listOf = (): HTMLElement => byPart("command-palette-list");

/** The trigger's props come from the skin, not the primitive: it is the element with `aria-haspopup`. */
export const triggerOf = (mounted: MountedPalette): HTMLElement => {
  const trigger = mounted.root.querySelector<HTMLElement>('[aria-haspopup="dialog"]');
  if (trigger === null) {
    throw new Error("the palette has no trigger");
  }
  return trigger;
};

/** The rows, in the order the primitive's results put them. */
export const rowsOf = (): HTMLElement[] => [
  ...document.querySelectorAll<HTMLElement>('[data-part="command-palette-item"]'),
];

/** What the list shows, as the labels a reader reads: the primitive's results, rendered by the skin. */
export const visibleLabels = (): string[] => rowsOf().map((row) => row.textContent ?? "");

export const activeId = (): string | null => inputOf().getAttribute("aria-activedescendant");

/** A press on the field (or the panel), as a keyboard does it. */
export const press = (
  target: Element,
  key: string,
  init: KeyboardEventInit = {},
): KeyboardEvent => {
  const event = new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init });
  target.dispatchEvent(event);
  flush();
  return event;
};

/** Real typing in the field, replacing what is there; then a flush, so the list is read after Solid applied it. */
export const type = async (text: string): Promise<void> => {
  const input = inputOf();
  input.focus();
  input.select();
  await userEvent.keyboard(text);
  flush();
};

/** Opens the palette from its trigger, which is what a page does. */
export const open = async (mounted: MountedPalette): Promise<void> => {
  await userEvent.click(triggerOf(mounted));
  flush();
};

/** Opens the palette through the primitive, for a host that binds its own chord. */
export const openThrough = (mounted: MountedPalette): void => {
  paletteOf(mounted).openPalette();
  flush();
};

/** Runs the row with this label with the pointer. */
export const clickRow = async (label: string): Promise<void> => {
  const row = rowsOf().find((candidate) => candidate.textContent === label);
  if (row === undefined) {
    throw new Error(`the list has no row ${label}`);
  }
  await userEvent.click(row);
  flush();
};

// The command palette's conformance test: the composition has no APG spec (the primitive is a dialog + a text field + a
// status, not a new pattern), so this walks the kit's own DOM instead of replaying a scenario. What it pins is the split:
// the primitive owns the filter, the active option and the keys; the skin owns the dialog layer, the field's look and the
// highlight — painted from the announcement, never from a copy of the active index.
import { flush } from "solid-js";
import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import {
  activeId,
  clickRow,
  inputOf,
  layerOf,
  listOf,
  open,
  openThrough,
  paletteOf,
  panelOf,
  press,
  rowsOf,
  triggerOf,
  type,
  visibleLabels,
} from "./command-palette-driver.ts";
import { type MountedPalette, mountPalette } from "./command-palette.fixture.tsx";

const style = (element: Element): CSSStyleDeclaration => getComputedStyle(element);
const byPart = <T extends HTMLElement = HTMLElement>(name: string): T => {
  const element = document.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`the palette has no ${name}`);
  }
  return element;
};

const live: MountedPalette[] = [];
const mounted = (config?: Parameters<typeof mountPalette>[0]): MountedPalette => {
  const instance = mountPalette(config);
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

describe("the kit's command palette", () => {
  it("opens from its trigger into a modal dialog whose field holds the focus", async () => {
    const instance = mounted();
    const palette = paletteOf(instance);
    const trigger = triggerOf(instance);
    expect(trigger.getAttribute("aria-haspopup")).toBe("dialog");
    expect(trigger.getAttribute("aria-expanded")).toBe("false");
    expect(layerOf()).toBeNull();

    await open(instance);

    // the trigger says the dialog is up, and the layer is the portal's: a child of the body, not of the fixture
    expect(trigger.getAttribute("aria-expanded")).toBe("true");
    const layer = layerOf();
    expect(layer).not.toBeNull();
    expect(layer!.parentElement).toBe(document.body);
    expect(layer!.getAttribute("data-part")).toBe("command-palette-layer");
    // the wash under the panel is the dialog's backdrop, and it closes the palette
    expect(byPart("command-palette-backdrop").id).toBe(palette.backdropProps.id);

    const panel = panelOf();
    expect(panel.getAttribute("role")).toBe("dialog");
    expect(panel.getAttribute("aria-modal")).toBe("true");
    expect(panel.getAttribute("aria-labelledby")).toBe(palette.titleProps.id);
    // the title is the name of the dialog and of the listbox, so it is in the panel though nothing shows it
    const title = byPart("command-palette-title");
    expect(title.id).toBe(palette.titleProps.id);
    expect(title.textContent).toBe("Command palette");
    expect(style(title).clipPath).toBe("inset(50%)");

    const input = inputOf();
    expect(input.getAttribute("role")).toBe("searchbox");
    expect(input.getAttribute("type")).toBe("text");
    expect(input.value).toBe("");
    expect(document.activeElement).toBe(input);
    expect(input.getAttribute("aria-controls")).toBe(listOf().id);
    expect(listOf().getAttribute("role")).toBe("listbox");
    expect(listOf().getAttribute("aria-labelledby")).toBe(palette.titleProps.id);
    expect(input.getAttribute("aria-activedescendant")).toBe(palette.optionProps("deploy").id);

    const rows = rowsOf();
    expect(rows.map((row) => row.getAttribute("role"))).toEqual([
      "option",
      "option",
      "option",
      "option",
    ]);
    expect(rows.map((row) => row.tabIndex)).toEqual([-1, -1, -1, -1]);
    // the highlight is the primitive's announcement: one row says yes, the rest say no, and the skin keeps no index
    expect(rows.map((row) => row.getAttribute("aria-selected"))).toEqual([
      "true",
      "false",
      "false",
      "false",
    ]);
    // the groups the primitive reports head their rows
    expect(
      [...panel.querySelectorAll('[data-part="command-palette-group"]')].map(
        (group) => group.getAttribute("role") ?? "",
      ),
    ).toEqual(["group", "group"]);
    expect(byPart("command-palette-empty").hidden).toBe(true);

    const status = byPart("command-palette-status");
    expect(status.getAttribute("role")).toBe("status");
    expect(status.getAttribute("aria-live")).toBe("polite");
    expect(status.textContent).toBe("4 commands");
  });

  it("renders the primitive's results, not a filter of its own", async () => {
    const instance = mounted();
    const palette = paletteOf(instance);
    await open(instance);
    const ids = (): string[] => palette.results().map((result) => result.id);

    expect(visibleLabels()).toEqual(palette.results().map((result) => result.label));

    await type("roll");
    expect(ids()).toEqual(["rollback"]);
    expect(visibleLabels()).toEqual(["Roll back"]);
    expect(activeId()).toBe(palette.optionProps("rollback").id);
    // the rollback keyword match is the primitive's too
    expect(visibleLabels()).toEqual(palette.results().map((result) => result.label));

    await type("production");
    expect(visibleLabels()).toEqual(["Deploy"]);

    await type("PREFERENCES");
    expect(visibleLabels()).toEqual(["Open settings"]);

    await type("zzz");
    expect(palette.results()).toEqual([]);
    expect(rowsOf()).toEqual([]);
    expect(activeId()).toBeNull();
    // the empty state is the primitive's `hidden`, and the count is announced once per query
    const empty = byPart("command-palette-empty");
    expect(empty.hidden).toBe(false);
    expect(empty.textContent).toBe("No commands found");
    expect(byPart("command-palette-status").textContent).toBe("No commands");
  });

  it("moves aria-activedescendant with the arrows and paints the row it names", async () => {
    const instance = mounted();
    const palette = paletteOf(instance);
    await open(instance);
    const input = inputOf();
    const rows = rowsOf();
    const selected = (): (string | null)[] => rows.map((row) => row.getAttribute("aria-selected"));

    // the highlight is the row the primitive names, and it is painted from that attribute
    expect(style(rows[0]!).backgroundColor).not.toBe(style(rows[1]!).backgroundColor);
    press(input, "ArrowDown");
    expect(activeId()).toBe(palette.optionProps("rollback").id);
    expect(selected()).toEqual(["false", "true", "false", "false"]);
    expect(style(rows[1]!).backgroundColor).not.toBe(style(rows[2]!).backgroundColor);

    press(input, "ArrowDown");
    press(input, "ArrowDown");
    expect(activeId()).toBe(palette.optionProps("settings").id);
    expect(selected()).toEqual(["false", "false", "false", "true"]);

    // ↓ on the last row returns the highlight to the field, and it paints no row
    press(input, "ArrowDown");
    expect(activeId()).toBeNull();
    expect(selected()).toEqual(["false", "false", "false", "false"]);
    // and ↓ from the field enters at the first row, ↑ at the last
    press(input, "ArrowDown");
    expect(activeId()).toBe(palette.optionProps("deploy").id);
    press(input, "ArrowUp");
    expect(activeId()).toBe(palette.optionProps("settings").id);
  });

  it("runs the highlighted command on Enter, closes, and returns the focus", async () => {
    const instance = mounted();
    const palette = paletteOf(instance);
    const trigger = triggerOf(instance);
    await open(instance);
    const input = inputOf();

    // the arrow moves the highlight; Enter runs the row it names, not the first one
    press(input, "ArrowDown");
    expect(activeId()).toBe(palette.optionProps("rollback").id);
    press(input, "Enter");

    expect(instance.chosen).toEqual(["rollback"]);
    expect(layerOf()).toBeNull();
    expect(document.activeElement).toBe(trigger);
  });

  it("closes on Escape and returns the focus to whatever had it", async () => {
    const instance = mounted();
    const trigger = triggerOf(instance);
    await open(instance);
    expect(document.activeElement).toBe(inputOf());

    press(inputOf(), "Escape");
    expect(layerOf()).toBeNull();
    expect(document.activeElement).toBe(trigger);
    // the query is the primitive's and it resets on close, so the next open starts from the corpus
    expect(paletteOf(instance).query()).toBe("");
  });

  it("runs a command clicked with the pointer and keeps the focus in the field", async () => {
    const instance = mounted();
    const palette = paletteOf(instance);
    await open(instance);
    const input = inputOf();

    await clickRow("Open settings");

    expect(instance.chosen).toEqual(["settings"]);
    expect(layerOf()).toBeNull();
    // the primitive cancels the mouse-down, so the press never moved the DOM focus
    expect(document.activeElement).toBe(triggerOf(instance));
    expect(palette.open()).toBe(false);
    expect(input.isConnected).toBe(false);
  });

  it("keeps the field's focus after a press on the panel, so Escape still closes it", async () => {
    const instance = mounted();
    await open(instance);
    // a heading is not a control: the press must not move the focus out of the field the dialog listens from
    await userEvent.click(
      document.querySelector<HTMLElement>('[data-part="command-palette-group-label"]')!,
    );
    flush();
    expect(document.activeElement).toBe(inputOf());
    press(inputOf(), "Escape");
    expect(layerOf()).toBeNull();
  });

  it("stands outside a transformed, clipped ancestor, and can be sent to a host's own root", async () => {
    const instance = mounted({ hostile: true });
    const host = instance.root.querySelector<HTMLElement>('[data-part="palette-host"]')!;
    expect(style(host).transform).not.toBe("none");

    await open(instance);
    const layer = layerOf()!;
    // inline, the transformed ancestor would be the containing block of `position: fixed` and clip the layer
    expect(layer.closest('[data-part="palette-host"]')).toBeNull();
    expect(layer.parentElement).toBe(document.body);
    expect(layer.offsetParent).toBeNull();
    expect(layer.getBoundingClientRect().width).toBe(window.innerWidth);

    // `mount` is the host's own modal root, as the dialog's is
    press(inputOf(), "Escape");
    const root = document.createElement("div");
    document.body.append(root);
    const owned = mounted({ mount: root });
    openThrough(owned);
    expect(root.querySelector('[data-part="command-palette-layer"]')?.parentElement).toBe(root);
    root.remove();
  });

  it("binds the page chord it is given, and nothing when it is told not to", async () => {
    const quiet = mounted();
    // the fixture's default is `hotkey: false`, so the page keeps its keys
    press(document.body, "k", { ctrlKey: true });
    expect(layerOf()).toBeNull();

    const bound = mounted({ hotkey: "ctrl+k" });
    press(document.body, "k", { ctrlKey: true });
    expect(layerOf()).not.toBeNull();
    expect(document.activeElement).toBe(inputOf());
    // the same chord closes it again
    press(document.body, "k", { ctrlKey: true });
    expect(layerOf()).toBeNull();

    // a host that binds its own chord opens the palette through the primitive
    openThrough(quiet);
    expect(layerOf()).not.toBeNull();
    await userEvent.keyboard("{Escape}");
    flush();
    expect(layerOf()).toBeNull();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
